function(container, apiUrl, tables) {
  let currentOrderItems = [];
  let storeData = [];
  let productData = [];
  let demandForecastData = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗マスタ
      storeData = await window.aivicApi.list(1) || [];
      // 商品マスタ
      productData = await window.aivicApi.list(2) || [];
      // 需要予測結果
      demandForecastData = await window.aivicApi.list(8) || [];

      renderStoreOptions();
      renderCategoryOptions();
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
    }
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    const validStores = storeData.filter(store => store.有効フラグ);

    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
      validStores.map(store => 
        `<option value="${store.店舗ID}">${store.店舗名} (${store.店舗コード})</option>`
      ).join('');
  }

  // カテゴリ選択肢を描画
  function renderCategoryOptions() {
    const categoryFilter = container.querySelector('#category-filter');
    const categories = [...new Set(productData.map(p => p.商品カテゴリID).filter(Boolean))];

    categoryFilter.innerHTML = '<option value="">全てのカテゴリ</option>' +
      categories.map(cat => `<option value="${cat}">カテゴリ${cat}</option>`).join('');
  }

  // 発注商品一覧を描画
  function renderOrderItems() {
    const tbody = container.querySelector('#order-items-tbody');
    const storeId = container.querySelector('#store-select').value;
    const categoryFilter = container.querySelector('#category-filter').value;

    if (!storeId) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">店舗を選択してください</td></tr>';
      return;
    }

    // 選択店舗の需要予測データを取得
    let forecasts = demandForecastData.filter(f => f.店舗ID === storeId);

    // カテゴリフィルター適用
    if (categoryFilter) {
      const categoryProducts = productData.filter(p => p.商品カテゴリID === categoryFilter);
      const categoryProductIds = categoryProducts.map(p => p.商品ID);
      forecasts = forecasts.filter(f => categoryProductIds.includes(f.商品ID));
    }

    if (forecasts.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 40px;">データがありません</td></tr>';
      currentOrderItems = [];
      updateSummary();
      return;
    }

    currentOrderItems = forecasts.map(forecast => {
      const product = productData.find(p => p.商品ID === forecast.商品ID) || {};
      return {
        商品ID: forecast.商品ID,
        商品コード: product.商品コード || '',
        商品名: product.商品名 || '',
        予測需要数量: forecast.予測数量 || 0,
        推奨発注数量: forecast.推奨発注数量 || 0,
        現在在庫数量: Math.floor(Math.random() * 100), // 仮の在庫数
        発注数量: forecast.推奨発注数量 || 0,
        発注単価: product.単価 || 0,
        発注金額: (forecast.推奨発注数量 || 0) * (product.単価 || 0),
        selected: false
      };
    });

    tbody.innerHTML = currentOrderItems.map((item, index) => `
      <tr data-index="${index}">
        <td><input type="checkbox" class="item-checkbox" data-index="${index}"></td>
        <td>${item.商品コード}</td>
        <td>${item.商品名}</td>
        <td style="text-align: right;">${item.予測需要数量.toLocaleString()}</td>
        <td style="text-align: right;">${item.推奨発注数量.toLocaleString()}</td>
        <td style="text-align: right;">${item.現在在庫数量.toLocaleString()}</td>
        <td>
          <input type="number" class="input quantity-input" data-index="${index}" 
                 value="${item.発注数量}" min="0" max="999999" style="width: 80px;">
        </td>
        <td style="text-align: right;">¥${item.発注単価.toLocaleString()}</td>
        <td style="text-align: right;" class="amount-cell" data-index="${index}">¥${item.発注金額.toLocaleString()}</td>
        <td>
          <button class="action-btn secondary single-order-btn" data-index="${index}">発注</button>
        </td>
      </tr>
    `).join('');

    updateSummary();
  }

  // 発注数量変更時の金額計算
  function updateAmount(index) {
    const quantityInput = container.querySelector(`input[data-index="${index}"]`);
    const quantity = parseInt(quantityInput.value) || 0;

    // バリデーション
    if (quantity < 0) {
      alert('発注数量は0以上の値を入力してください');
      quantityInput.value = 0;
      return;
    }

    if (quantity > 999999) {
      alert('発注数量が上限値を超えています');
      quantityInput.value = 999999;
      return;
    }

    // 小数点チェック
    if (quantityInput.value.includes('.')) {
      alert('発注数量は整数で入力してください');
      quantityInput.value = Math.floor(quantity);
      return;
    }

    currentOrderItems[index].発注数量 = quantity;
    currentOrderItems[index].発注金額 = quantity * currentOrderItems[index].発注単価;

    const amountCell = container.querySelector(`.amount-cell[data-index="${index}"]`);
    amountCell.textContent = `¥${currentOrderItems[index].発注金額.toLocaleString()}`;

    updateSummary();
  }

  // 合計情報更新
  function updateSummary() {
    const selectedItems = currentOrderItems.filter((item, index) => {
      const checkbox = container.querySelector(`input[data-index="${index}"]`);
      return checkbox && checkbox.checked;
    });

    const selectedCount = selectedItems.length;
    const totalAmount = selectedItems.reduce((sum, item) => sum + item.発注金額, 0);

    container.querySelector('#selected-count').textContent = selectedCount;
    container.querySelector('#total-amount').textContent = `¥${totalAmount.toLocaleString()}`;

    const bulkOrderBtn = container.querySelector('#btn-bulk-order');
    bulkOrderBtn.disabled = selectedCount === 0;
  }

  // 発注実行
  async function executeOrder(items) {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    // 過去日付チェック
    if (new Date(orderDate) < new Date(today)) {
      alert('発注日付は本日以降の日付を選択してください');
      return false;
    }

    // 発注数量チェック
    for (const item of items) {
      if (!item.発注数量 || item.発注数量 <= 0) {
        alert(`${item.商品名}の発注数量を正しく入力してください`);
        return false;
      }
    }

    try {
      for (const item of items) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(), // 7日後
          発注数量: item.発注数量,
          予測数量: item.予測需要数量,
          発注単価: item.発注単価,
          発注金額: item.発注金額,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001',
          発注理由: 'AI需要予測に基づく発注',
          自動発注フラグ: false,
          作成者ID: 'current-user',
          更新者ID: 'current-user'
        };

        await window.aivicApi.save(9, orderData);
      }

      alert(`${items.length}件の発注を実行しました`);
      return true;
    } catch (error) {
      console.error('発注実行エラー:', error);
      alert('発注実行中にエラーが発生しました');
      return false;
    }
  }

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(items) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#confirm-content');

    const totalAmount = items.reduce((sum, item) => sum + item.発注金額, 0);

    content.innerHTML = `
      <div style="margin-bottom: 16px;">
        <strong style="color: var(--text);">発注商品: ${items.length}件</strong>
      </div>
      <div style="max-height: 200px; overflow-y: auto; border: 1px solid var(--border); border-radius: 4px; padding: 8px;">
        ${items.map(item => `
          <div style="display: flex; justify-content: space-between; padding: 4px 0; border-bottom: 1px solid var(--border);">
            <span style="color: var(--text);">${item.商品名}</span>
            <span style="color: var(--text);">${item.発注数量}個 × ¥${item.発注単価.toLocaleString()} = ¥${item.発注金額.toLocaleString()}</span>
          </div>
        `).join('')}
      </div>
      <div style="margin-top: 16px; text-align: right;">
        <strong style="color: var(--text); font-size: 16px;">合計金額: ¥${totalAmount.toLocaleString()}</strong>
      </div>
    `;

    dialog.classList.remove('hidden');
  }

  // イベントリスナー設定

  // 店舗選択変更
  container.querySelector('#store-select').addEventListener('change', renderOrderItems);

  // カテゴリフィルター変更
  container.querySelector('#category-filter').addEventListener('change', renderOrderItems);

  // 更新ボタン
  container.querySelector('#btn-refresh').addEventListener('click', async () => {
    await loadInitialData();
    renderOrderItems();
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.item-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
    updateSummary();
  });

  // まとめて発注実行ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', () => {
    const selectedItems = currentOrderItems.filter((item, index) => {
      const checkbox = container.querySelector(`input[data-index="${index}"]`);
      return checkbox && checkbox.checked;
    });

    if (selectedItems.length === 0) {
      alert('発注する商品を選択してください');
      return;
    }

    showOrderConfirmDialog(selectedItems);
  });

  // 発注確認ダイアログのボタン
  container.querySelector('#btn-cancel-order').addEventListener('click', () => {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  container.querySelector('#btn-execute-order').addEventListener('click', async () => {
    const selectedItems = currentOrderItems.filter((item, index) => {
      const checkbox = container.querySelector(`input[data-index="${index}"]`);
      return checkbox && checkbox.checked;
    });

    const success = await executeOrder(selectedItems);
    if (success) {
      container.querySelector('#order-confirm-dialog').classList.add('hidden');
      renderOrderItems(); // 画面更新
    }
  });

  // イベントデリゲーション
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('quantity-input')) {
      const index = parseInt(e.target.dataset.index);
      updateAmount(index);
    }
  });

  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('item-checkbox')) {
      updateSummary();
    }
  });

  container.addEventListener('click', async (e) => {
    // 単品発注ボタン
    if (e.target.classList.contains('single-order-btn')) {
      const index = parseInt(e.target.dataset.index);
      const item = currentOrderItems[index];

      if (!item.発注数量 || item.発注数量 <= 0) {
        alert('発注数量を入力してください');
        return;
      }

      showOrderConfirmDialog([item]);
    }
  });

  // 初期データ読み込み
  loadInitialData();
}
